import{_ as o,c as t,o as l,ah as i}from"./chunks/framework.CvbyeFFO.js";const u=JSON.parse('{"title":"SWE 其他相关工作","description":"","frontmatter":{"title":"SWE 其他相关工作","date":"2026-05-06T15:20:41.000Z","create":"2026-05-06T15:20:41.000Z","categories":[],"tags":[]},"headers":[],"relativePath":"posts/domain/swe/11-swe-other-work.md","filePath":"posts/domain/swe/11-swe-other-work.md","lastUpdated":null}'),c={name:"posts/domain/swe/11-swe-other-work.md"};function a(d,e,r,n,s,g){return l(),t("div",null,e[0]||(e[0]=[i('<h2 id="_2604-swe-chat-stanford" tabindex="-1">(2604) SWE-chat (Stanford) <a class="header-anchor" href="#_2604-swe-chat-stanford" aria-label="Permalink to &quot;(2604) SWE-chat (Stanford)&quot;">​</a></h2><p>🌺 <strong>论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">SWE-chat 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://alphaxiv.org/abs/2604.20779" target="_blank" rel="noreferrer">paper</a></li></ul><p><strong>核心方法</strong></p><ul><li><code>SWE-chat 数据集收集框架</code><ul><li>借助开源工具 <code>Entire.io CLI</code>，在真实开发环境中静默捕获用户的完整交互日志。</li><li><code>交互轨迹</code> + <code>Git 差异版本控制</code> 结合，实现代码级的 <code>人类与 AI 归属权追踪</code> (line-level attribution)。</li></ul></li><li><code>数据规模</code>：205 个公开 GitHub 仓库，6,000+ Agent 会话，6.3万+ 用户 Prompt，35.5万+ 工具调用。</li></ul><p><strong>关键发现</strong></p><ul><li><code>使用模式呈现双峰分布</code>：41% 的会话属于全自动的 <code>“Vibe Coding”</code>（AI 编写 &gt;99% 的代码），而 23% 是纯人类编写（AI 仅辅助）。</li><li><code>效率低下</code>：Agent 生成的代码中，最终存活并被提交的比例仅为 <code>44%</code>。</li><li><code>安全性差</code>：Vibe Coding 引入的安全漏洞是纯人类编码的 <code>9倍</code>。</li><li><code>摩擦频发</code>：Agent 极少主动提问（&lt;2%），但用户在 <code>44%</code> 的对话轮次中会打断或推翻 AI 的输出。</li></ul><p><strong>关键贡献</strong></p><ul><li>构建了<code>首个</code>包含真实开发者与 AI 编码助手交互轨迹的大规模数据集 <code>SWE-chat</code>。</li><li>揭示了现有 AI 编码 Agent 在真实工作流中的<code>真实表现与失效模式</code>，打破了仅依赖静态 Benchmark 评估的局限。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>❓<strong>问题背景</strong></p><h4 id="现有-benchmark-无法反映真实工作流" tabindex="-1">现有 Benchmark 无法反映真实工作流 <a class="header-anchor" href="#现有-benchmark-无法反映真实工作流" aria-label="Permalink to &quot;现有 Benchmark 无法反映真实工作流&quot;">​</a></h4><div class="custom-block warning"><div class="custom-block-title">问题背景</div><p><strong>真实交互数据缺失</strong></p><ul><li>尽管 AI 编码 Agent 已被大规模采用，但学术界和工业界都缺乏对其在<code>真实工作环境</code>中表现的实证研究。</li><li>现有评估（如 SWE-bench）通常局限于<code>静态的、定义明确的 Issue</code> 和一次性代码补丁生成。</li></ul><p><strong>Benchmark 与实际用法的脱节</strong></p><ul><li>真实开发是<code>迭代式</code>的：用户会频繁修改需求、纠正 Agent 错误、甚至中途改变主意。</li><li>Agent 在真实开发中需要执行极其多样的任务（如阅读理解旧代码、跑 bash 脚本），而现有 Benchmark 过度侧重于“写代码解决 Bug”。</li><li>仅在 Benchmark 上得分高，无法代表能成为一个好的、无摩擦的“真实人类助手”。</li></ul></div><h3 id="swe-chat-数据集与分析框架" tabindex="-1">SWE-chat 数据集与分析框架 <a class="header-anchor" href="#swe-chat-数据集与分析框架" aria-label="Permalink to &quot;SWE-chat 数据集与分析框架&quot;">​</a></h3><p>📕<strong>核心方法</strong></p><h4 id="数据收集与特征" tabindex="-1">数据收集与特征 <a class="header-anchor" href="#数据收集与特征" aria-label="Permalink to &quot;数据收集与特征&quot;">​</a></h4><div class="custom-block important"><div class="custom-block-title">SWE-chat 收集流水线</div><p><strong>自动化捕获 (Entire.io CLI)</strong></p><ul><li>开发者授权安装插件后，工具在后台自动记录会话日志（Prompt、思考过程、工具调用、Bash 输出等）。</li><li><code>代码归属权追踪</code>：利用影子分支（shadow branches）在每次工具调用后进行差异对比，精准标记提交代码中“哪些是人类写的”、“哪些是 AI 写的”。</li></ul><p><strong>数据集多维标注 (基于 LLM 裁判)</strong></p><ul><li><code>会话成功率 (Session Success)</code>：0-100分，评估 Agent 是否最终满足了用户目标。</li><li><code>用户画像 (User Persona)</code>：分为 <code>专家挑刺型 (Expert Nitpicker)</code>、<code>模糊请求型 (Vague Requester)</code>、<code>朝令夕改型 (Mind Changer)</code>。</li><li><code>意图分类 (Prompt Intent)</code>：创建、重构、调试、理解、Git 操作等。</li><li><code>用户反馈 (User Pushback)</code>：纠正 (Correction)、拒绝 (Rejection)、报错 (Failure report)。</li></ul></div><h3 id="实验与分析设置" tabindex="-1">实验与分析设置 <a class="header-anchor" href="#实验与分析设置" aria-label="Permalink to &quot;实验与分析设置&quot;">​</a></h3><p>✍️<strong>实验设置</strong></p><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>分析对象</strong></p><ul><li>真实开发者在使用五种主流编码 Agent（主要是 <code>Claude Code</code>，约占 85%）时的完整轨迹。</li></ul><p><strong>量化指标</strong></p><ul><li><code>代码留存率 (Code Survival Rate)</code>：Agent 最终留在 Commit 中的代码行数 / Agent 生成的净代码行数。</li><li><code>成本效率 (Cost Efficiency)</code>：每提交 100 行代码消耗的 Token 数量或 API 费用。</li><li><code>代码安全性 (Semgrep)</code>：对比 Commit 前后的代码快照，计算每 1000 行代码引入的新漏洞数量。</li></ul></div><h3 id="关键结果-真实场景下的-agent-表现" tabindex="-1">关键结果 (真实场景下的 Agent 表现) <a class="header-anchor" href="#关键结果-真实场景下的-agent-表现" aria-label="Permalink to &quot;关键结果 (真实场景下的 Agent 表现)&quot;">​</a></h3><p>🍑<strong>关键结果</strong></p><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>用户到底在用 Agent 做什么？ (RQ1)</strong></p><ul><li><code>阅读理解是最大需求</code>：最常见的意图是“理解现有代码”（19%），其次才是“写新代码”（13.4%）。</li><li><code>工具调用的分布</code>：高达 <code>33%</code> 的工具调用是执行 Bash 命令（如构建、Git 操作），说明 Agent 很大一部分时间在与系统环境交互，而非单纯改文件。</li><li><code>用户大多是“挑刺专家”</code>：在大多数会话（约 40%）中，人类保持目标不变，但会对 AI 的执行细节提出非常具体、苛刻的纠正。</li></ul><p><strong>Agent 的失败模式与低效表现 (RQ2)</strong></p><ul><li><code>极度浪费算力</code>：Vibe Coding 模式虽然在流行，但效率极低。每提交 100 行代码，Vibe Coding 的 Token 消耗和资金成本约是人机协同 (Collaborative) 模式的 <code>3倍</code>。</li><li><code>安全性显著下降</code>：Vibe Coding 引入漏洞的速度是人类纯手工编码的 <code>~9倍</code>，是人机协同模式的 <code>~5倍</code>（包含路径遍历、SQL注入等）。</li><li><code>盲目的自主性</code>：Agent 的运行时间越来越长（长尾达到 100 分钟），但几乎从不主动停下来向用户提问求助（&lt;2% 的轮次）。</li><li><code>人类被迫进行高频干预</code>：因为 Agent 不问问题，用户不得不在 <code>44%</code> 的轮次中进行“硬打断”或提交“报错/纠正”来强行纠偏。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><p>⛳ <strong>未来方向</strong></p><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>Benchmark 的范式转移</strong></p><ul><li>开发基于“多轮交互”和“代码理解”的新型基准测试，而不仅仅是评估补丁生成能力。</li><li>测试 Agent 在给定真实对话上下文时，预测下一步最合理操作的能力。</li></ul><p><strong>人机交互 (HCI) 设计的改进</strong></p><ul><li>AI Agent 获取自主权的速度过快，导致缺乏对不确定性的感知。</li><li>未来需要设计更具适应性的界面与机制，教导 Agent <strong>“何时该主动停下来询问人类”</strong>。</li></ul><p><strong>基于真实数据的用户模拟器</strong></p><ul><li>依赖人类做活体测试太贵，静态 Benchmark 又不准。</li><li>可利用 SWE-chat 数据集训练大规模的 <code>用户模拟器 (User Simulators)</code>，在离线状态下更真实地模拟人类开发者的挑剔反馈和打断行为，以评估新一代 Agent。</li></ul></div>',20)]))}const p=o(c,[["render",a]]);export{u as __pageData,p as default};
